package ai.eva.android.probe;
import java.io.*;import java.util.*;import java.util.zip.*;
/** APK ZIP/DEX inventory without executing code, extracting files, or claiming decompilation. */
final class ApkInventory {
 static int i32(byte[] b,int p)throws IOException{if(p<0||p+4>b.length)throw new IOException("Invalid DEX offset");long n=PacketSummary.u32(b,p,true);if(n>Integer.MAX_VALUE)throw new IOException("Oversized DEX offset");return (int)n;}
 static String string(byte[] b,int id,int count,int offset)throws IOException{if(id<0||id>=count)throw new IOException("Invalid DEX string index");int p=i32(b,offset+id*4);for(int n=0;n<5;n++){if(p>=b.length)throw new IOException("Truncated DEX string");if((b[p++]&128)==0)break;}int end=p;while(end<b.length&&b[end]!=0&&end-p<4096)end++;return new String(b,p,end-p,java.nio.charset.StandardCharsets.UTF_8);}
 static String inspect(File file,String query)throws Exception{if(file.length()>512L*1024*1024)throw new IOException("APK 超过 512 MB");List<String> matches=new ArrayList<>(),libs=new ArrayList<>(),configs=new ArrayList<>();int dexCount=0,classes=0,entries;long expanded=0;try(ZipFile zip=new ZipFile(file)){entries=zip.size();if(entries>50000)throw new IOException("APK 条目过多");Enumeration<? extends ZipEntry> it=zip.entries();while(it.hasMoreElements()){ZipEntry e=it.nextElement();String name=e.getName();if(name.startsWith("lib/")&&name.endsWith(".so")&&libs.size()<100)libs.add(name);if(name.startsWith("res/xml/")&&name.toLowerCase(Locale.ROOT).contains("network")&&configs.size()<30)configs.add(name);if(!name.matches("classes[0-9]*\\.dex"))continue;if(++dexCount>40)throw new IOException("DEX 数量过多");byte[] b;try(InputStream in=zip.getInputStream(e)){b=DocumentPreview.bounded(in,32*1024*1024);}expanded+=b.length;if(expanded>256L*1024*1024)throw new IOException("DEX 解压内容过大");if(b.length<112||!new String(b,0,4,"US-ASCII").equals("dex\n"))throw new IOException("不支持的 DEX 容器");int strings=i32(b,56),so=i32(b,60),types=i32(b,64),to=i32(b,68),count=i32(b,96),co=i32(b,100);if(strings>2000000||types>1000000||count>1000000||(long)so+4L*strings>b.length||(long)to+4L*types>b.length||(long)co+32L*count>b.length)throw new IOException("DEX 表结构无效");classes+=count;for(int n=0;n<count;n++){int type=i32(b,co+n*32);if(type>=types)throw new IOException("Invalid class type");String cls=string(b,i32(b,to+type*4),strings,so);if(cls.startsWith("L")&&cls.endsWith(";"))cls=cls.substring(1,cls.length()-1).replace('/','.');if(matches.size()<100&&cls.toLowerCase(Locale.ROOT).contains(query.toLowerCase(Locale.ROOT)))matches.add(cls);}}}StringBuilder out=new StringBuilder("{\"executed\":false,\"decompiled\":false,\"entries\":").append(entries).append(",\"dexFiles\":").append(dexCount).append(",\"classCount\":").append(classes).append(",\"matches\":");array(out,matches);out.append(",\"nativeLibraries\":");array(out,libs);out.append(",\"networkResourceCandidates\":");array(out,configs);return out.append('}').toString();}
 static void array(StringBuilder out,List<String> values){out.append('[');for(int n=0;n<values.size();n++){if(n>0)out.append(',');out.append(PacketSummary.quote(values.get(n)));}out.append(']');}
}
